-- =============================================================================
-- Vê AI · PostgreSQL · Seed de demonstração
-- Mesmos dados do repositório database (tools/dataset.json): 3 regiões, 4 cidadãos,
-- 2 gestores, 20 descrições e 15 relatos. Datas relativas ao momento da carga.
-- Senha de todos os usuários: Veai@2026
-- Só insere se o banco estiver vazio (pode rodar quantas vezes quiser).
-- =============================================================================
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM usuario) THEN
    -- REGIAO (latitude/longitude = centro aproximado do bairro)
    -- USUARIO
    -- GESTOR_REGIAO
    -- DESCRICAO
    -- RELATO (prioridade = peso da gravidade × (1 + apoios) + dias em aberto; 0 se finalizado)
    -- APOIO_RELATO
    -- ATUALIZACAO_RELATO
    -- As colunas IDENTITY continuam depois dos IDs fixos
    PERFORM setval(pg_get_serial_sequence('regiao', 'id'), (SELECT MAX(id) FROM regiao));
    PERFORM setval(pg_get_serial_sequence('usuario', 'id'), (SELECT MAX(id) FROM usuario));
    PERFORM setval(pg_get_serial_sequence('descricao', 'id'), (SELECT MAX(id) FROM descricao));
    PERFORM setval(pg_get_serial_sequence('relato', 'id'), (SELECT MAX(id) FROM relato));
  END IF;
END $$;
